export function decAKnowledgeOracle(n:number,b:GeneratedBody,v:number[]){
 const prompt=b.prompt.map(x=>x.type==="paragraph"?x.text:"").join(""),options=b.choices.map(c=>c.map(x=>x.type==="paragraph"?x.text:"").join(""));let truth:boolean[];
 if(n===16||n===18){decAFixedKnowledgeOracle(n,b,v);return;}
 if(definitions[n]){const f=definitions[n],target=f.targets.findIndex(s=>prompt.includes(s));assert.equal(target,v[0]);assert(target>=0);assert(/説明|役割|利用目的|該当|防ぐ方法/.test(prompt));assert(!/適切でない|不適切|誤った/.test(prompt));truth=options.map(s=>{const found=f.concepts.flatMap((p,i)=>p.test(s)?[i]:[]);assert.equal(found.length,1,`Q${n} reviewed concept ${s}`);return found[0]===target;});
 }else if(termCases[n]){const f=termCases[n],matches=f.prompts.flatMap((p,i)=>p.test(prompt)?[i]:[]);assert.deepEqual(matches,[v[0]]);assert.deepEqual([...options].sort(),[...f.labels].sort());truth=options.map(x=>x===f.labels[matches[0]]);
 }else if(statements[n]){const f=statements[n];assert.match(prompt,f.stem);truth=options.map(s=>{const yes=f.yes.filter(p=>p.test(s)),no=f.no.filter(p=>p.test(s));assert.equal(yes.length+no.length,1,`Q${n} statement must be reviewed: ${s}`);return yes.length===1;});
 }else if(n===10){assert.equal(prompt,"外部割込みの原因となるものはどれか。");const externals=["タイマーによる時間経過の通知","入出力装置からの処理完了の通知","外部装置からの処理要求の通知"],internals=["ゼロによる除算命令の実行","存在しない命令コードの実行","ページフォールトの発生"];truth=options.map(s=>{assert([...externals,...internals].includes(s));return externals.includes(s);});
 }else if(n===48){const target=prompt.match(/、(可用性|機密性|完全性)を確認/)![1],facts:Record<string,string>={"外部記憶媒体の無断持出しが禁止されていること":"機密性","中断時間を定めたSLAの水準が保たれるよう管理されていること":"可用性","データ入力時の誤り検査が適切に行われていること":"完全性","保存データが暗号化されていること":"機密性","暗号鍵を適切に管理して保存データを暗号化していること":"機密性","障害時の復旧時間を測定していること":"可用性","データの改ざんを認証符号で検出していること":"完全性","停電に備え予備電源を設けていること":"可用性","障害に備え機器を冗長化していること":"可用性","機密データの閲覧権限を限定していること":"機密性","入力データの検査と改ざんの検出を実施していること":"完全性","通信の内容を暗号化していること":"機密性"};truth=options.map(s=>{assert(s in facts);return facts[s]===target;});
 }else if(n===56){assert.equal(prompt,"CGM（Consumer Generated Media）の例はどれか。");const no=["企業が投資家に経営状況や財務状況を公開する自社のWebサイト","企業が一般消費者に自社商品の特徴や使用方法を発信する自社のWebサイト","行政機関が市民に政策や行政サービスを公開する自組織のWebサイト"],yes=["個人が使用した商品の評価を、不特定多数へ発信するブログやSNS","利用者同士が自ら撮影・制作した動画を投稿し、感想を交換するサイト","消費者が旅行先の体験や飲食店の評価を投稿して共有するサイト"];truth=options.map(s=>{assert([...yes,...no].includes(s));return yes.includes(s);});
 }else throw Error(`Missing knowledge oracle Q${n}`);
 assert.equal(new Set(options).size,4);assert.deepEqual(truth.flatMap((x,i)=>x?[i]:[]),[b.correctIndex]);
}
